WITH exploded AS (SELECT id, service, level, latency_ms, status_code, k, value FROM app_logs LATERAL VIEW EXPLODE(context) t AS k, value) SELECT id, level, latency_ms, status_code, k, AVG(status_code) OVER (PARTITION BY service ORDER BY latency_ms, id, k ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS status_code_avg_6_prior, STDDEV_SAMP(status_code) OVER (PARTITION BY level) AS level_stddev_samp_status_code, DENSE_RANK() OVER (ORDER BY status_code DESC) AS status_code_dense_rank FROM exploded
